-- ID: 20261121010000_clear_legacy_barbecue_catalog
-- =========================================================================

LOCK TABLE 
    public.itens_carrinho,
    public.itens_pedido,
    public.pedido_estoque_efeitos,
    public.movimentacoes_estoque,
    public.produtos,
    public.base_conhecimento
IN EXCLUSIVE MODE;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.itens_pedido ip 
        JOIN public.pedidos p ON p.id = ip.pedido_id 
        WHERE ip.produto_id IN (
            'a1111111-1111-4111-8111-111111111111',
            'a2222222-2222-4222-8222-222222222222',
            'a3333333-3333-4333-8333-333333333333',
            'a4444444-4444-4444-8444-444444444444',
            'b1111111-1111-4111-8111-111111111111',
            'b2222222-2222-4222-8222-222222222222',
            'b3333333-3333-4333-8333-333333333333',
            'b4444444-4444-4444-8444-444444444444',
            'c1111111-1111-4111-8111-111111111111',
            'c2222222-2222-4222-8222-222222222222',
            'c3333333-3333-4333-8333-333333333333',
            'c4444444-4444-4444-8444-444444444444',
            'd1111111-1111-4111-8111-111111111111'
        ) AND p.status::text NOT IN ('cancelado')
    ) THEN
        RAISE EXCEPTION 'Não é possível remover produtos históricos com pedidos concluídos associados';
    END IF;
END $$;

